import {blankProject,blankDiagram,demoDiagram,nextFlowName,clone,uid} from './model.js';
import {esc} from './canvas.js';
import {icon} from './components.js';

export function setupProjectUI({store,canEdit,modal,toast,actions,legacy}){
 const $=s=>document.querySelector(s);let targetFlowId=null,createInPlace=false,lastVisibleFlow=null;
 function requestFlow(inPlace=false){
  if(!canEdit())return;createInPlace=inPlace;targetFlowId=store.diagram.id;
  modal('New flow',`<p>Create a flow inside <strong>${esc(store.project.name)}</strong>.</p><label class="field"><span>Flow name</span><input id="flow-name" maxlength="100" value="${esc(inPlace?store.diagram.name:nextFlowName(store.project))}" autofocus></label>`,`<button class="button" data-action="close-modal">Cancel</button><button class="button primary" data-action="create-flow">Create flow</button>`);
 }
 function nameInput(){const name=$('#flow-name').value.trim();if(!name){toast('Enter a flow name');$('#flow-name').focus();return null;}return name;}
 function settings(){const p=store.project;modal('Project settings',`<p>All ${p.diagrams.length} flow${p.diagrams.length===1?'':'s'} are saved together in one project XML.</p><label class="field"><span>Project name</span><input id="project-name-input" maxlength="100" value="${esc(p.name)}" ${canEdit()?'':'readonly'}></label><div class="field-row"><label class="field"><span>Version</span><input id="project-version-input" value="${esc(p.version)}" ${canEdit()?'':'readonly'}></label><label class="field"><span>Author</span><input id="project-author-input" value="${esc(p.author)}" ${canEdit()?'':'readonly'}></label></div><label class="field"><span>Description</span><textarea id="project-description-input" ${canEdit()?'':'readonly'}>${esc(p.description)}</textarea></label>`,`<button class="button" data-action="close-modal">Close</button>${canEdit()?'<button class="button primary" data-action="save-project-settings">Save changes</button>':''}`);}
 function menu(items,anchor){const el=$('#context-menu');el.innerHTML=items;el.hidden=false;const r=anchor?.getBoundingClientRect()||$('#project-title').getBoundingClientRect();el.style.left=Math.max(8,Math.min(r.left,innerWidth-230))+'px';el.style.top=Math.max(8,Math.min(r.bottom+6,innerHeight-el.offsetHeight-12))+'px';el.querySelector('button:not(:disabled)')?.focus();}
 function flowMenu(event){targetFlowId=event.target.closest('[data-flow-id]')?.dataset.flowId||store.diagram.id;const disabled=canEdit()?'':'disabled';menu(`<button data-action="rename-flow" ${disabled}>${icon('note')}Rename flow</button><button data-action="duplicate-flow" ${disabled}>${icon('copy')}Duplicate flow</button><hr><button class="danger" data-action="delete-flow" ${store.project.diagrams.length>1?disabled:'disabled'}>${icon('trash')}Delete flow</button>`,event.target.closest('button'));}
 Object.assign(actions,{
  'project-settings':settings,
  'project-menu'(event){menu(`<button data-action="new-project" ${canEdit()?'':'disabled'}>${icon('folder')}New project</button><button data-action="project-settings">${icon('layers')}Project settings</button><hr><button data-action="open">${icon('folder')}Open project XML</button><button data-action="save">${icon('save')}Save project XML</button>${legacy?'<hr><button data-action="recover-legacy">'+icon('undo')+'Recover previous workspace</button>':''}`,event.target.closest('button'));},
  'save-project-settings'(){if(!canEdit())return;const name=$('#project-name-input').value.trim();if(!name){toast('Enter a project name');return;}const version=$('#project-version-input').value,author=$('#project-author-input').value,description=$('#project-description-input').value;store.commit((d,p)=>Object.assign(p,{name,version,author,description}));$('#modal').close();toast('Project updated');},
  'new-project'(){if(!canEdit())return;modal('New project',`<label class="field"><span>Project name</span><input id="new-project-name" placeholder="e.g. API manufacturing development" maxlength="100" autofocus></label><p>The new project starts with an empty flow. Save your current project XML to keep a separate copy. This change can also be undone.</p>`,`<button class="button" data-action="close-modal">Cancel</button><button class="button" data-action="save">Save current project</button><button class="button primary" data-action="create-project">Create project</button>`);},
  'create-project'(){if(!canEdit())return;const name=$('#new-project-name').value.trim();if(!name){toast('Enter a project name');return;}store.replace(blankProject(name));$('#modal').close();toast('Project created · add your first components');},
  new(){requestFlow(false);},'start-flow'(){requestFlow(true);},
  'create-flow'(){if(!canEdit())return;const name=nameInput();if(!name)return;try{if(createInPlace){store.commit((d,p)=>{const flow=p.diagrams.find(f=>f.id===targetFlowId);if(!flow)throw Error('Flow no longer exists');flow.name=name;});}else{const flow=blankDiagram();flow.name=name;flow.settings.theme=store.diagram.settings.theme;store.addFlow(flow);}$('#modal').close();toast('Flow ready · add components from the library');}catch(e){toast(e.message);}},
  demo(){if(!canEdit())return;try{const flow=demoDiagram();flow.name=nextFlowName(store.project,flow.name);flow.settings.theme=store.diagram.settings.theme;store.addFlow(flow);toast('Example added as a new flow');}catch(e){toast(e.message);}},
  'flow-menu':flowMenu,
  'rename-flow'(){if(!canEdit())return;const flow=store.project.diagrams.find(d=>d.id===(targetFlowId||store.diagram.id));if(!flow)return;targetFlowId=flow.id;modal('Rename flow',`<label class="field"><span>Flow name</span><input id="flow-name" maxlength="100" value="${esc(flow.name)}" autofocus></label>`,`<button class="button" data-action="close-modal">Cancel</button><button class="button primary" data-action="confirm-rename-flow">Rename</button>`);},
  'confirm-rename-flow'(){if(!canEdit())return;const name=nameInput();if(!name)return;store.commit((d,p)=>{const f=p.diagrams.find(f=>f.id===targetFlowId);if(f)f.name=name;});$('#modal').close();toast('Flow renamed');},
  'duplicate-flow'(){if(!canEdit())return;try{store.duplicateFlow(targetFlowId||store.diagram.id);toast('Flow duplicated');}catch(e){toast(e.message);}},
  'delete-flow'(){if(!canEdit())return;const flow=store.project.diagrams.find(d=>d.id===(targetFlowId||store.diagram.id));if(!flow)return;targetFlowId=flow.id;if(store.project.diagrams.length===1){toast('Keep at least one flow in the project');return;}modal('Delete flow?',`<p>Delete <strong>${esc(flow.name)}</strong> and its ${flow.nodes.length} components from this project? You can undo this change.</p>`,`<button class="button" data-action="close-modal">Cancel</button><button class="button danger" data-action="confirm-delete-flow">Delete flow</button>`);},
  'confirm-delete-flow'(){if(!canEdit())return;try{store.deleteFlow(targetFlowId);$('#modal').close();toast('Flow deleted · Undo to restore');}catch(e){toast(e.message);}},
  'recover-legacy'(){if(!canEdit()||!legacy)return;try{const flow=clone(legacy);flow.id=uid('diagram');flow.name=nextFlowName(store.project,flow.name);store.addFlow(flow);toast('Previous workspace recovered as a new flow');}catch(e){toast(e.message);}}
 });
 function renderTabs(){
  const p=store.project;$('#flow-tabs').innerHTML=p.diagrams.map((d,i)=>`<div class="flow-tab ${d.id===p.activeDiagramId?'active':''}"><button role="tab" id="flow-tab-${esc(d.id)}" aria-selected="${d.id===p.activeDiagramId}" aria-controls="diagram-stage" tabindex="${d.id===p.activeDiagramId?'0':'-1'}" data-flow-select="${esc(d.id)}" title="${esc(d.name)} · Double-click to rename">${icon('layers',15)}<span>${esc(d.name||'Untitled flow')}</span></button>${d.id===p.activeDiagramId?`<button class="flow-tab-menu" data-action="flow-menu" data-flow-id="${esc(d.id)}" title="Flow actions" aria-label="Actions for ${esc(d.name)}">${icon('more',16)}</button>`:''}</div>`).join('');
  $('#flow-counter').textContent=p.diagrams.length;$('#flow-counter').title=p.diagrams.length+' flows in this project';$('#diagram-stage').setAttribute('aria-labelledby','flow-tab-'+p.activeDiagramId);
  document.querySelectorAll('[data-action="new"],[data-action="demo"],[data-action="start-flow"]').forEach(b=>b.disabled=!canEdit());
  $('#legacy-recovery').hidden=!legacy;if(lastVisibleFlow!==p.activeDiagramId){lastVisibleFlow=p.activeDiagramId;requestAnimationFrame(()=>$('#flow-tabs [aria-selected="true"]')?.scrollIntoView({block:'nearest',inline:'nearest'}));}
 }
 $('#flow-tabs').addEventListener('click',e=>{const b=e.target.closest('[data-flow-select]');if(b)store.switchFlow(b.dataset.flowSelect);});
 $('#flow-tabs').addEventListener('dblclick',e=>{const b=e.target.closest('[data-flow-select]');if(b){targetFlowId=b.dataset.flowSelect;actions['rename-flow']();}});
 $('#flow-tabs').addEventListener('contextmenu',e=>{const b=e.target.closest('[data-flow-select]');if(b){e.preventDefault();targetFlowId=b.dataset.flowSelect;menu(`<button data-action="rename-flow" ${canEdit()?'':'disabled'}>${icon('note')}Rename flow</button><button data-action="duplicate-flow" ${canEdit()?'':'disabled'}>${icon('copy')}Duplicate flow</button><hr><button class="danger" data-action="delete-flow" ${canEdit()&&store.project.diagrams.length>1?'':'disabled'}>${icon('trash')}Delete flow</button>`,b);}});
 $('#flow-tabs').addEventListener('keydown',e=>{const b=e.target.closest('[data-flow-select]');if(!b)return;const flows=store.project.diagrams;let index=flows.findIndex(d=>d.id===b.dataset.flowSelect);if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();e.stopPropagation();index=e.key==='Home'?0:e.key==='End'?flows.length-1:(index+(e.key==='ArrowRight'?1:-1)+flows.length)%flows.length;store.switchFlow(flows[index].id);$('#flow-tabs [aria-selected="true"]').focus();}else if(e.key==='F2'){e.preventDefault();targetFlowId=b.dataset.flowSelect;actions['rename-flow']();}});
 return {renderTabs};
}
